#!/usr/bin/env python3
"""
PDDL Airport Plan Validator

Parses PDDL domain and problem files, then simulates plan execution step by step,
checking preconditions before each action and applying effects. Finally verifies
the goal is satisfied.
"""

import re
import sys


def tokenize(text):
    """Tokenize a PDDL string into a list of tokens (parentheses and words)."""
    # Remove comments (lines starting with ;)
    text = re.sub(r';[^\n]*', '', text)
    # Add spaces around parentheses for easy splitting
    text = text.replace('(', ' ( ').replace(')', ' ) ')
    return text.split()


def parse_sexp(tokens, idx):
    """Parse an S-expression from tokens starting at idx.
    Returns (parsed_structure, next_idx)."""
    if idx >= len(tokens):
        raise ValueError("Unexpected end of tokens")

    if tokens[idx] == '(':
        lst = []
        idx += 1  # skip '('
        while idx < len(tokens) and tokens[idx] != ')':
            elem, idx = parse_sexp(tokens, idx)
            lst.append(elem)
        if idx >= len(tokens):
            raise ValueError("Missing closing parenthesis")
        idx += 1  # skip ')'
        return lst, idx
    else:
        return tokens[idx], idx + 1


def parse_pddl_file(filepath):
    """Parse a PDDL file and return the top-level S-expression."""
    with open(filepath, 'r') as f:
        text = f.read()
    tokens = tokenize(text)
    result, _ = parse_sexp(tokens, 0)
    return result


def extract_predicates_from_conjunction(sexp):
    """Extract a list of (positive, predicate_tuple) from a conjunction.
    Returns list of (True/False, tuple_of_strings).
    True = positive predicate, False = negated predicate."""
    predicates = []

    if not isinstance(sexp, list):
        return predicates

    # Check if it's (and ...)
    if len(sexp) > 0 and sexp[0] == 'and':
        for item in sexp[1:]:
            predicates.extend(extract_predicates_from_conjunction(item))
    elif len(sexp) > 0 and sexp[0] == 'not':
        # (not (pred args...))
        inner = sexp[1]
        if isinstance(inner, list):
            predicates.append((False, tuple(inner)))
        else:
            predicates.append((False, (inner,)))
    elif len(sexp) > 0 and isinstance(sexp[0], str) and sexp[0] not in ('and', 'not'):
        # It's a positive predicate: (pred args...)
        predicates.append((True, tuple(sexp)))
    else:
        # Could be nested; try to recurse
        for item in sexp:
            if isinstance(item, list):
                predicates.extend(extract_predicates_from_conjunction(item))

    return predicates


def substitute(pred_tuple, param_name, value):
    """Substitute ?a (or any param) with a concrete value in a predicate tuple."""
    return tuple(value if x == param_name else x for x in pred_tuple)


def find_section(sexp, keyword):
    """Find a section in an S-expression by keyword (e.g., ':init', ':goal')."""
    for i, item in enumerate(sexp):
        if item == keyword:
            return sexp[i + 1] if i + 1 < len(sexp) else None
    return None


def parse_domain(filepath):
    """Parse a PDDL domain file and return a dict of actions.
    Each action has 'params', 'preconditions', 'effects'."""
    sexp = parse_pddl_file(filepath)

    actions = {}
    # Walk through the top-level define form
    # sexp = ['define', ['domain', name], ...]
    for item in sexp:
        if isinstance(item, list) and len(item) > 0 and item[0] == ':action':
            action_name = item[1]

            # Find parameter name
            param_name = '?a'  # default
            for i, elem in enumerate(item):
                if elem == ':parameters':
                    params_list = item[i + 1]
                    # params_list is like ['?a', '-', 'airplane']
                    if isinstance(params_list, list) and len(params_list) > 0:
                        param_name = params_list[0]
                    break

            # Find precondition
            preconditions = []
            for i, elem in enumerate(item):
                if elem == ':precondition':
                    preconditions = extract_predicates_from_conjunction(item[i + 1])
                    break

            # Find effect
            effects = []
            for i, elem in enumerate(item):
                if elem == ':effect':
                    effects = extract_predicates_from_conjunction(item[i + 1])
                    break

            actions[action_name] = {
                'param': param_name,
                'preconditions': preconditions,
                'effects': effects,
            }

    return actions


def parse_problem(filepath):
    """Parse a PDDL problem file and return (init_state, goal_conditions).
    init_state is a set of ground predicate tuples.
    goal_conditions is a list of (positive, pred_tuple)."""
    sexp = parse_pddl_file(filepath)

    init_state = set()
    goal_conditions = []

    for item in sexp:
        if isinstance(item, list) and len(item) > 0:
            if item[0] == ':init':
                # Each element after :init is a ground predicate
                for pred in item[1:]:
                    if isinstance(pred, list):
                        init_state.add(tuple(pred))
            elif item[0] == ':goal':
                # item[1] is the goal formula (usually an 'and' conjunction)
                goal_conditions = extract_predicates_from_conjunction(item[1])

    return init_state, goal_conditions


def parse_plan(filepath):
    """Parse a plan file. Each line is like:
    action_name(airplane_CFBEG)
    Returns list of (action_name, argument)."""
    steps = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith(';'):
                continue
            # Parse: action_name(arg)
            match = re.match(r'^([^(]+)\(([^)]+)\)\s*$', line)
            if match:
                action_name = match.group(1).strip()
                arg = match.group(2).strip()
                steps.append((action_name, arg))
            else:
                print(f"  WARNING: Could not parse plan line: {line}")
    return steps


def validate_plan(domain_file, problem_file, plan_file, task_name):
    """Validate a plan against domain and problem definitions.
    Returns True if valid, False otherwise."""
    print(f"{'=' * 60}")
    print(f"Validating {task_name}")
    print(f"  Domain:  {domain_file}")
    print(f"  Problem: {problem_file}")
    print(f"  Plan:    {plan_file}")
    print(f"{'=' * 60}")

    # Parse domain
    actions = parse_domain(domain_file)
    print(f"  Parsed {len(actions)} actions from domain.")

    # Parse problem
    state, goal_conditions = parse_problem(problem_file)
    print(f"  Parsed {len(state)} initial state predicates.")
    print(f"  Parsed {len(goal_conditions)} goal conditions.")

    # Parse plan
    plan_steps = parse_plan(plan_file)
    print(f"  Parsed {len(plan_steps)} plan steps.")
    print()

    # Simulate execution
    valid = True
    for step_num, (action_name, arg) in enumerate(plan_steps, 1):
        print(f"  Step {step_num}: {action_name}({arg})")

        if action_name not in actions:
            print(f"    ERROR: Action '{action_name}' not found in domain!")
            valid = False
            break

        action = actions[action_name]
        param = action['param']

        # Check preconditions
        precond_ok = True
        for positive, pred_tuple in action['preconditions']:
            ground_pred = substitute(pred_tuple, param, arg)
            if positive:
                if ground_pred not in state:
                    print(f"    PRECONDITION FAILED: {ground_pred} not in state")
                    precond_ok = False
            else:
                if ground_pred in state:
                    print(f"    PRECONDITION FAILED: {ground_pred} should NOT be in state")
                    precond_ok = False

        if not precond_ok:
            print(f"    ERROR: Preconditions not met for step {step_num}!")
            valid = False
            break

        print(f"    Preconditions OK.")

        # Apply effects
        adds = []
        deletes = []
        for positive, pred_tuple in action['effects']:
            ground_pred = substitute(pred_tuple, param, arg)
            if positive:
                adds.append(ground_pred)
            else:
                deletes.append(ground_pred)

        for d in deletes:
            state.discard(d)
        for a in adds:
            state.add(a)

        print(f"    Applied effects: +{len(adds)} -{len(deletes)} predicates.")

    print()

    if not valid:
        print(f"  RESULT: Plan is INVALID (action precondition failure)")
        print()
        return False

    # Check goal
    goal_ok = True
    for positive, pred_tuple in goal_conditions:
        if positive:
            if pred_tuple not in state:
                print(f"  GOAL FAILED: {pred_tuple} not in final state")
                goal_ok = False
        else:
            if pred_tuple in state:
                print(f"  GOAL FAILED: {pred_tuple} should NOT be in final state")
                goal_ok = False

    if goal_ok:
        print(f"  RESULT: Plan is VALID! All preconditions met and goal achieved.")
    else:
        print(f"  RESULT: Plan is INVALID (goal not satisfied)")

    print()
    return goal_ok


def main():
    tasks = [
        {
            'name': 'Task 01',
            'domain': '/app/airport/domain01.pddl',
            'problem': '/app/airport/task01.pddl',
            'plan': '/app/task01.txt',
        },
        {
            'name': 'Task 02',
            'domain': '/app/airport/domain02.pddl',
            'problem': '/app/airport/task02.pddl',
            'plan': '/app/task02.txt',
        },
    ]

    results = []
    for task in tasks:
        ok = validate_plan(task['domain'], task['problem'], task['plan'], task['name'])
        results.append((task['name'], ok))

    print("=" * 60)
    print("SUMMARY")
    print("=" * 60)
    all_valid = True
    for name, ok in results:
        status = "VALID" if ok else "INVALID"
        print(f"  {name}: {status}")
        if not ok:
            all_valid = False

    return 0 if all_valid else 1


if __name__ == '__main__':
    sys.exit(main())
